// path: apps/web/src/app/(app)/settings/SettingsClient.tsx
"use client";

import {
    clearSettingsPrefs,
    defaultSettingsPrefs,
    downloadJsonFile,
    formatDateTime,
    normalizeSettingsPrefs,
    readSettingsPrefs,
    SettingsPrefs,
    writeSettingsPrefs,
} from "@/lib/settings/prefs";
import { useTheme } from "next-themes";
import React from "react";

type SaveState = "idle" | "dirty" | "saving" | "saved" | "error";

type SettingsUser = {
  id: string;
  email: string;
  name: string | null;
  role: "user" | "admin";
  avatarDataUrl: string | null;
};

function clonePrefs(value: SettingsPrefs): SettingsPrefs {
  return JSON.parse(JSON.stringify(value)) as SettingsPrefs;
}

function classNames(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

function getSaveMeta(state: SaveState) {
  switch (state) {
    case "dirty":
      return {
        label: "Chưa lưu",
        containerClass:
          "bg-[var(--warning-soft)] text-[var(--warning)] border border-[var(--warning)]/15",
      };
    case "saving":
      return {
        label: "Đang lưu...",
        containerClass:
          "bg-[var(--accent-soft)] text-[var(--accent)] border border-[var(--accent)]/15",
      };
    case "saved":
      return {
        label: "Đã lưu",
        containerClass:
          "bg-[var(--success-soft)] text-[var(--success)] border border-[var(--success)]/15",
      };
    case "error":
      return {
        label: "Lưu lỗi",
        containerClass:
          "bg-[var(--danger-soft)] text-[var(--danger)] border border-[var(--danger)]/15",
      };
    default:
      return {
        label: "Ổn định",
        containerClass:
          "bg-[var(--bg-soft)] app-text-soft border border-[var(--border-main)]",
      };
  }
}

function getInitials(name?: string | null, email?: string | null) {
  const source = name?.trim() || email?.trim() || "U";
  const parts = source.split(/\s+/).filter(Boolean);
  if (parts.length >= 2) {
    return `${parts[0][0] ?? ""}${parts[1][0] ?? ""}`.toUpperCase();
  }
  return source.slice(0, 1).toUpperCase();
}

function applyPrefsToDom(
  prefs: SettingsPrefs,
  setTheme: (theme: string) => void
) {
  setTheme(prefs.theme);
  document.documentElement.dataset.density = prefs.density;

  try {
    window.localStorage.setItem("mydtu.language", prefs.language);
  } catch {}
}

async function readFileAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("Không đọc được file ảnh."));
    reader.readAsDataURL(file);
  });
}

async function loadImageFromDataUrl(dataUrl: string) {
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error("Không tải được ảnh."));
    img.src = dataUrl;
  });
}

async function compressAvatar(file: File) {
  const dataUrl = await readFileAsDataUrl(file);
  const image = await loadImageFromDataUrl(dataUrl);

  const maxSize = 512;
  let width = image.width;
  let height = image.height;

  if (width > maxSize || height > maxSize) {
    const ratio = Math.min(maxSize / width, maxSize / height);
    width = Math.round(width * ratio);
    height = Math.round(height * ratio);
  }

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Không tạo được canvas để xử lý ảnh.");

  ctx.drawImage(image, 0, 0, width, height);

  const output = canvas.toDataURL("image/jpeg", 0.86);

  if (output.length > 2_000_000) {
    throw new Error("Ảnh quá lớn sau khi nén. Hãy chọn ảnh nhỏ hơn.");
  }

  return output;
}

export default function SettingsClient() {
  const { setTheme, resolvedTheme } = useTheme();

  const [prefs, setPrefs] = React.useState<SettingsPrefs>(defaultSettingsPrefs);
  const [initialPrefs, setInitialPrefs] =
    React.useState<SettingsPrefs>(defaultSettingsPrefs);
  const [user, setUser] = React.useState<SettingsUser | null>(null);

  const [loading, setLoading] = React.useState(true);
  const [saveState, setSaveState] = React.useState<SaveState>("idle");
  const [message, setMessage] = React.useState("");
  const [avatarBusy, setAvatarBusy] = React.useState(false);
  const [avatarPreviewOpen, setAvatarPreviewOpen] = React.useState(false);

  const [deleteOpen, setDeleteOpen] = React.useState(false);
  const [deleteConfirmText, setDeleteConfirmText] = React.useState("");
  const [deletePassword, setDeletePassword] = React.useState("");
  const [deleteBusy, setDeleteBusy] = React.useState(false);
  const [logoutBusy, setLogoutBusy] = React.useState(false);

  const fileInputRef = React.useRef<HTMLInputElement | null>(null);

  React.useEffect(() => {
    let alive = true;

    async function bootstrap() {
      try {
        const local = readSettingsPrefs();
        if (!alive) return;

        setPrefs(local);
        setInitialPrefs(local);
        applyPrefsToDom(local, setTheme);

        const res = await fetch("/api/settings", { cache: "no-store" });
        const json = await res.json().catch(() => null);

        if (!alive) return;

        if (res.ok && json?.ok) {
          const normalized = normalizeSettingsPrefs(json.settings);
          setPrefs(normalized);
          setInitialPrefs(normalized);
          setUser(json.user ?? null);
          writeSettingsPrefs(normalized);
          applyPrefsToDom(normalized, setTheme);
        }
      } catch (error) {
        if (!alive) return;
        setMessage(String((error as Error)?.message || error));
      } finally {
        if (alive) setLoading(false);
      }
    }

    bootstrap();

    return () => {
      alive = false;
    };
  }, [setTheme]);

  React.useEffect(() => {
    const a = JSON.stringify(prefs);
    const b = JSON.stringify(initialPrefs);

    if (a !== b) {
      setSaveState((prev) => (prev === "saving" ? prev : "dirty"));
    } else {
      setSaveState((prev) => (prev === "saving" ? prev : "idle"));
    }
  }, [prefs, initialPrefs]);

  const saveMeta = getSaveMeta(saveState);
  const initials = getInitials(user?.name, user?.email);

  function updatePrefs(updater: (prev: SettingsPrefs) => SettingsPrefs) {
    setPrefs((prev) => updater(clonePrefs(prev)));
  }

  async function handleSave() {
    try {
      setSaveState("saving");
      setMessage("");

      writeSettingsPrefs(prefs);
      applyPrefsToDom(prefs, setTheme);

      const res = await fetch("/api/settings", {
        method: "PUT",
        headers: { "content-type": "application/json" },
        cache: "no-store",
        body: JSON.stringify({
          ...prefs,
          avatarDataUrl: user?.avatarDataUrl ?? null,
        }),
      });

      const json = await res.json().catch(() => null);

      if (!res.ok || !json?.ok) {
        throw new Error(json?.message || json?.error || "Lưu cài đặt thất bại.");
      }

      const normalized = normalizeSettingsPrefs(json.settings);
      setPrefs(normalized);
      setInitialPrefs(normalized);
      setUser(json.user ?? null);

      writeSettingsPrefs(normalized);
      applyPrefsToDom(normalized, setTheme);

      window.dispatchEvent(
        new CustomEvent("mydtu:settings-updated", {
          detail: {
            user: json.user,
            settings: normalized,
          },
        })
      );

      setSaveState("saved");
      setMessage("Đã lưu cài đặt thành công.");
    } catch (error) {
      setSaveState("error");
      setMessage(String((error as Error)?.message || error));
    }
  }

  function handleRestoreDefaults() {
    const next = clonePrefs(defaultSettingsPrefs);
    setPrefs(next);
    setMessage("Đã khôi phục cài đặt mặc định. Nhấn Lưu để áp dụng.");
    setSaveState("dirty");
  }

  function handleExportJson() {
    const next = clonePrefs(prefs);
    next.data.lastExportAt = new Date().toISOString();

    setPrefs(next);
    setMessage("Đã xuất file JSON cài đặt.");
    setSaveState("dirty");

    downloadJsonFile("mydtu-settings.json", {
      exportedAt: new Date().toISOString(),
      app: "MYDTU Assistant",
      version: "settings.v2",
      user: user
        ? {
            id: user.id,
            email: user.email,
            name: user.name,
            role: user.role,
          }
        : null,
      prefs: next,
    });
  }

  function handleClearUiCache() {
    try {
      window.localStorage.removeItem("mydtu.settings.v1");
      window.localStorage.removeItem("mydtu.language");
      window.localStorage.removeItem("mydtu.onboarding.dismissed");
      window.localStorage.removeItem("mydtu.ui.cache");
    } catch {}

    const next = clonePrefs(defaultSettingsPrefs);
    setPrefs(next);
    setInitialPrefs(next);
    applyPrefsToDom(next, setTheme);

    setMessage("Đã xoá cache giao diện và reset cài đặt local.");
    setSaveState("saved");
  }

  function handleQuickSync() {
    updatePrefs((prev) => {
      prev.data.lastManualSyncAt = new Date().toISOString();
      return prev;
    });

    setMessage("Đồng bộ nhanh thành công. Nhấn Lưu để ghi nhận thời gian sync.");
    setSaveState("dirty");
  }

  function handleResetOnboarding() {
    try {
      window.localStorage.removeItem("mydtu.onboarding.dismissed");
    } catch {}

    updatePrefs((prev) => {
      prev.data.onboardingDismissed = false;
      return prev;
    });

    setMessage("Đã reset onboarding. Nhấn Lưu để hoàn tất.");
    setSaveState("dirty");
  }

  async function handleLogout() {
    try {
      setLogoutBusy(true);
      setMessage("");

      const res = await fetch("/api/auth/logout", {
        method: "POST",
        cache: "no-store",
      });

      if (!res.ok) {
        throw new Error("Đăng xuất thất bại.");
      }

      window.location.href = "/login";
    } catch (error) {
      setMessage(String((error as Error)?.message || error));
    } finally {
      setLogoutBusy(false);
    }
  }

  async function handleDeleteAccount() {
    if (deleteConfirmText.trim().toUpperCase() !== "DELETE") {
      setMessage('Bạn phải nhập đúng "DELETE" để xác nhận.');
      return;
    }

    if (!deletePassword.trim()) {
      setMessage("Bạn phải nhập mật khẩu hiện tại để xoá tài khoản.");
      return;
    }

    setDeleteBusy(true);
    setMessage("");

    try {
      const res = await fetch("/api/account", {
        method: "DELETE",
        headers: { "content-type": "application/json" },
        cache: "no-store",
        body: JSON.stringify({
          confirmText: deleteConfirmText,
          password: deletePassword,
        }),
      });

      const json = await res.json().catch(() => null);

      if (!res.ok || !json?.ok) {
        throw new Error(json?.message || json?.error || "Xoá tài khoản thất bại.");
      }

      clearSettingsPrefs();
      window.location.href = "/login";
    } catch (error) {
      setMessage(String((error as Error)?.message || error));
    } finally {
      setDeleteBusy(false);
      setDeleteOpen(false);
      setDeleteConfirmText("");
      setDeletePassword("");
    }
  }

  async function handlePickAvatar(
    event: React.ChangeEvent<HTMLInputElement>
  ) {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      setAvatarBusy(true);
      setMessage("");

      if (!file.type.startsWith("image/")) {
        throw new Error("Chỉ chấp nhận file ảnh.");
      }

      const avatarDataUrl = await compressAvatar(file);

      setUser((prev) =>
        prev
          ? {
              ...prev,
              avatarDataUrl,
            }
          : null
      );

      setSaveState("dirty");
      setMessage("Đã chọn ảnh đại diện mới. Nhấn Lưu để áp dụng.");
    } catch (error) {
      setMessage(String((error as Error)?.message || error));
    } finally {
      setAvatarBusy(false);
      if (event.target) event.target.value = "";
    }
  }

  function handleRemoveAvatar() {
    setUser((prev) => (prev ? { ...prev, avatarDataUrl: null } : prev));
    setSaveState("dirty");
    setMessage("Đã xoá ảnh đại diện. Nhấn Lưu để áp dụng.");
  }

  if (loading) {
    return (
      <div className="mx-auto w-full max-w-7xl">
        <div className="app-card rounded-3xl p-8">
          <div className="text-sm app-text-muted">Đang tải cài đặt...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto w-full max-w-7xl space-y-5">
      <header className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Cài đặt</h1>
          <p className="mt-1 text-sm app-text-muted">
            Tùy chỉnh ứng dụng MYDTU Assistant theo cách dùng của bạn.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <div
            className={classNames(
              "rounded-2xl px-3 py-2 text-sm font-medium",
              saveMeta.containerClass
            )}
          >
            Trạng thái: {saveMeta.label}
          </div>

          <button
            type="button"
            onClick={handleSave}
            className="app-btn-primary rounded-2xl px-4 py-2 text-sm font-semibold"
          >
            Lưu thay đổi
          </button>
        </div>
      </header>

      {message ? (
        <div className="rounded-2xl border border-[var(--accent)]/15 bg-[var(--accent-soft)] px-4 py-3 text-sm text-[var(--accent)]">
          {message}
        </div>
      ) : null}

      <div className="grid grid-cols-1 gap-5 xl:grid-cols-[minmax(0,1fr)_320px]">
        <div className="space-y-5">
          <SectionCard>
            <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <button
                    type="button"
                    onClick={() => user?.avatarDataUrl && setAvatarPreviewOpen(true)}
                    className="group relative block"
                    title={user?.avatarDataUrl ? "Xem ảnh đại diện" : "Ảnh đại diện"}
                  >
                    {user?.avatarDataUrl ? (
                      <img
                        src={user.avatarDataUrl}
                        alt="Ảnh đại diện người dùng"
                        className="h-20 w-20 rounded-[24px] border border-[var(--border-main)] object-cover shadow-sm transition group-hover:opacity-95"
                      />
                    ) : (
                      <div className="flex h-20 w-20 items-center justify-center rounded-[24px] border border-[var(--border-main)] bg-[var(--accent-soft)] text-2xl font-bold text-[var(--accent)]">
                        {initials}
                      </div>
                    )}

                    <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 rounded-full bg-[var(--accent)] px-2.5 py-1 text-[11px] font-semibold text-white shadow-lg">
                      Đổi ảnh
                    </span>
                  </button>

                  <input
                    id="settings-avatar-upload"
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    aria-label="Chọn ảnh đại diện từ máy"
                    className="hidden"
                    onChange={handlePickAvatar}
                  />
                </div>

                <div>
                  <div className="text-xl font-semibold">
                    {user?.name || "Người dùng MYDTU"}
                  </div>
                  <div className="mt-1 text-sm app-text-muted">
                    {user?.email || "Chưa có email"}
                  </div>
                  <div className="mt-2 flex flex-wrap items-center gap-2">
                    <span className="inline-flex rounded-full bg-[var(--success-soft)] px-2.5 py-1 text-xs font-semibold text-[var(--success)]">
                      Active session
                    </span>
                    <span className="inline-flex rounded-full bg-[var(--accent-soft)] px-2.5 py-1 text-xs font-semibold capitalize text-[var(--accent)]">
                      {user?.role || "user"}
                    </span>
                  </div>
                </div>
              </div>

              <div className="flex flex-wrap gap-3">
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={avatarBusy}
                  className="app-btn rounded-2xl px-4 py-2 text-sm font-semibold"
                >
                  {avatarBusy ? "Đang xử lý ảnh..." : "Chọn avatar từ máy"}
                </button>

                <button
                  type="button"
                  onClick={handleRemoveAvatar}
                  className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-2 text-sm font-semibold"
                >
                  Xoá avatar
                </button>
              </div>
            </div>
          </SectionCard>

          <div className="grid grid-cols-1 gap-5 lg:grid-cols-2">
            <SectionCard
              title="Giao diện & ngôn ngữ"
              subtitle="Thiết lập theme, ngôn ngữ và mật độ hiển thị."
            >
              <div className="space-y-4">
                <FieldRow
                  label="Theme"
                  description="Đồng bộ toàn bộ giao diện theo tông sáng/tối."
                >
                  <div className="grid grid-cols-3 gap-2">
                    <ChoiceButton
                      active={prefs.theme === "light"}
                      onClick={() =>
                        updatePrefs((prev) => {
                          prev.theme = "light";
                          return prev;
                        })
                      }
                    >
                      Sáng
                    </ChoiceButton>
                    <ChoiceButton
                      active={prefs.theme === "dark"}
                      onClick={() =>
                        updatePrefs((prev) => {
                          prev.theme = "dark";
                          return prev;
                        })
                      }
                    >
                      Tối
                    </ChoiceButton>
                    <ChoiceButton
                      active={prefs.theme === "system"}
                      onClick={() =>
                        updatePrefs((prev) => {
                          prev.theme = "system";
                          return prev;
                        })
                      }
                    >
                      System
                    </ChoiceButton>
                  </div>
                </FieldRow>

                <FieldRow
                  htmlFor="settings-language"
                  label="Ngôn ngữ"
                  description="Chuẩn bị cho i18n toàn app."
                >
                  <select
                    id="settings-language"
                    aria-label="Chọn ngôn ngữ hiển thị"
                    value={prefs.language}
                    onChange={(e) =>
                      updatePrefs((prev) => {
                        prev.language = e.target.value as "vi" | "en";
                        return prev;
                      })
                    }
                    className="app-input w-full rounded-2xl px-3 py-2 text-sm outline-none"
                  >
                    <option value="vi">Tiếng Việt</option>
                    <option value="en">English</option>
                  </select>
                </FieldRow>

                <FieldRow
                  label="Mật độ hiển thị"
                  description="Thoải mái hoặc gọn hơn cho màn hình nhỏ."
                >
                  <div className="grid grid-cols-2 gap-2">
                    <ChoiceButton
                      active={prefs.density === "comfortable"}
                      onClick={() =>
                        updatePrefs((prev) => {
                          prev.density = "comfortable";
                          return prev;
                        })
                      }
                    >
                      Thoải mái
                    </ChoiceButton>
                    <ChoiceButton
                      active={prefs.density === "compact"}
                      onClick={() =>
                        updatePrefs((prev) => {
                          prev.density = "compact";
                          return prev;
                        })
                      }
                    >
                      Gọn
                    </ChoiceButton>
                  </div>
                </FieldRow>
              </div>
            </SectionCard>

            <SectionCard
              title="Thông báo"
              subtitle="Kiểm soát cảnh báo học tập và nhắc việc."
            >
              <div className="space-y-3">
                <ToggleRow
                  label="Email alerts"
                  description="Thông báo điểm, thay đổi quan trọng, cảnh báo học vụ."
                  checked={prefs.notifications.emailAlerts}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.notifications.emailAlerts = checked;
                      return prev;
                    })
                  }
                />
                <ToggleRow
                  label="Web push"
                  description="Hiển thị thông báo ngay trên trình duyệt."
                  checked={prefs.notifications.webPush}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.notifications.webPush = checked;
                      return prev;
                    })
                  }
                />
                <ToggleRow
                  label="Nhắc lịch học"
                  description="Nhắc trước giờ học."
                  checked={prefs.notifications.timetableReminders}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.notifications.timetableReminders = checked;
                      return prev;
                    })
                  }
                />
                <ToggleRow
                  label="Nhắc deadline"
                  description="Nhắc bài tập, kiểm tra, việc cần làm."
                  checked={prefs.notifications.deadlineReminders}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.notifications.deadlineReminders = checked;
                      return prev;
                    })
                  }
                />
                <ToggleRow
                  label="Cảnh báo điểm"
                  description="Báo khi có thay đổi điểm hoặc điểm thấp."
                  checked={prefs.notifications.gradeAlerts}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.notifications.gradeAlerts = checked;
                      return prev;
                    })
                  }
                />
                <ToggleRow
                  label="Tóm tắt tuần"
                  description="Gửi bản tóm tắt lịch và việc học mỗi tuần."
                  checked={prefs.notifications.weeklySummary}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.notifications.weeklySummary = checked;
                      return prev;
                    })
                  }
                />
              </div>
            </SectionCard>
          </div>

          <SectionCard
            title="Dữ liệu & đồng bộ"
            subtitle="Xuất dữ liệu, reset local cache, đồng bộ cấu hình."
          >
            <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
              <InfoBox
                title="Lần sync thủ công"
                value={formatDateTime(prefs.data.lastManualSyncAt)}
              />
              <InfoBox
                title="Lần export JSON"
                value={formatDateTime(prefs.data.lastExportAt)}
              />
              <InfoBox
                title="Onboarding"
                value={prefs.data.onboardingDismissed ? "Đã tắt" : "Đang bật"}
              />
            </div>

            <div className="mt-4 flex flex-wrap gap-3">
              <ActionButton primary onClick={handleQuickSync}>
                Sync now
              </ActionButton>

              <ActionButton onClick={handleExportJson}>
                Export JSON
              </ActionButton>

              <ActionButton dangerSoft onClick={handleClearUiCache}>
                Clear local cache
              </ActionButton>

              <ActionButton onClick={handleResetOnboarding}>
                Reset onboarding
              </ActionButton>

              <ActionButton onClick={handleRestoreDefaults}>
                Khôi phục mặc định
              </ActionButton>
            </div>

            <p className="mt-4 text-sm app-text-muted">
              Bản này đã hỗ trợ save settings theo tài khoản. localStorage chỉ còn
              là lớp fallback để tải nhanh hơn.
            </p>
          </SectionCard>

          <div className="grid grid-cols-1 gap-5 lg:grid-cols-2">
            <SectionCard
              title="Quyền riêng tư & bảo mật"
              subtitle="Các tùy chọn ảnh hưởng tới trải nghiệm và thu thập dữ liệu."
            >
              <div className="space-y-3">
                <ToggleRow
                  label="Remember device"
                  description="Giữ lại một số tùy chọn local cho thiết bị hiện tại."
                  checked={prefs.privacy.rememberDevice}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.privacy.rememberDevice = checked;
                      return prev;
                    })
                  }
                />
                <ToggleRow
                  label="Analytics opt-in"
                  description="Cho phép lưu sự kiện sử dụng ẩn danh để cải thiện UX."
                  checked={prefs.privacy.analyticsOptIn}
                  onChange={(checked) =>
                    updatePrefs((prev) => {
                      prev.privacy.analyticsOptIn = checked;
                      return prev;
                    })
                  }
                />
              </div>

              <div className="mt-4 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] p-4 text-sm app-text-muted">
                Avatar hiện đang lưu trực tiếp ở DB dạng dữ liệu ảnh nén. Khi sau
                này có object storage, bạn có thể chuyển sang lưu URL để tối ưu hơn.
              </div>
            </SectionCard>

            <SectionCard
              title="Thông tin ứng dụng"
              subtitle="Nguồn dữ liệu và tình trạng cài đặt hiện tại."
            >
              <div className="grid grid-cols-1 gap-3">
                <InfoLine
                  label="Nguồn dữ liệu"
                  value="MYDTU Portal + user settings DB"
                />
                <InfoLine label="Cơ chế giao diện" value="Next.js App Router" />
                <InfoLine
                  label="Theme đang render"
                  value={resolvedTheme || "dark"}
                />
                <InfoLine label="Version settings" value="v2.0" />
              </div>

              <div className="mt-4 rounded-2xl border border-[var(--accent)]/15 bg-[var(--accent-soft)] px-4 py-3 text-sm text-[var(--accent)]">
                Data provenance: cấu hình đang được đồng bộ theo tài khoản hiện tại
                và có thể dùng lại trên các phiên đăng nhập tiếp theo.
              </div>
            </SectionCard>
          </div>

          <SectionCard
            title="Vùng nguy hiểm"
            subtitle="Các thao tác nhạy cảm cần xác nhận trước khi thực hiện."
          >
            <div className="flex flex-col gap-3 lg:flex-row">
              <button
                type="button"
                onClick={handleLogout}
                disabled={logoutBusy}
                className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3 text-sm font-semibold transition hover:opacity-90 disabled:opacity-60"
              >
                {logoutBusy ? "Đang đăng xuất..." : "Đăng xuất"}
              </button>

              <button
                type="button"
                onClick={() => setDeleteOpen(true)}
                className="rounded-2xl bg-red-600 px-4 py-3 text-sm font-semibold text-white transition hover:opacity-90"
              >
                Xoá tài khoản
              </button>
            </div>

            <p className="mt-4 text-sm app-text-muted">
              Khuyến nghị production: yêu cầu xác thực lại mật khẩu trước khi xoá tài khoản.
            </p>
          </SectionCard>
        </div>

        <div className="space-y-5">
          <SectionCard title="Tổng quan nhanh">
            <div className="grid grid-cols-1 gap-3">
              <QuickInfoCard
                label="Theme"
                value={
                  prefs.theme === "dark"
                    ? "Tối"
                    : prefs.theme === "light"
                    ? "Sáng"
                    : "System"
                }
              />
              <QuickInfoCard
                label="Ngôn ngữ"
                value={prefs.language === "vi" ? "Tiếng Việt" : "English"}
              />
              <QuickInfoCard
                label="Mật độ"
                value={prefs.density === "comfortable" ? "Thoải mái" : "Gọn"}
              />
              <QuickInfoCard
                label="Email alerts"
                value={prefs.notifications.emailAlerts ? "Bật" : "Tắt"}
              />
              <QuickInfoCard
                label="Web push"
                value={prefs.notifications.webPush ? "Bật" : "Tắt"}
              />
            </div>
          </SectionCard>

          <SectionCard title="Checklist chuyên nghiệp">
            <div className="space-y-3 text-sm">
              <ChecklistItem done>Theme sáng / tối / system</ChecklistItem>
              <ChecklistItem done>Lưu local fallback</ChecklistItem>
              <ChecklistItem done>Load/save DB theo user</ChecklistItem>
              <ChecklistItem done>Avatar chọn file từ máy</ChecklistItem>
              <ChecklistItem done>Xem preview ảnh đại diện</ChecklistItem>
              <ChecklistItem done>Danger zone + confirm modal</ChecklistItem>
              <ChecklistItem>
                Đồng bộ web push thật với browser permission
              </ChecklistItem>
              <ChecklistItem>
                Re-auth mạnh hơn trước khi xoá tài khoản
              </ChecklistItem>
            </div>
          </SectionCard>
        </div>
      </div>

      {avatarPreviewOpen && user?.avatarDataUrl ? (
        <ImagePreviewModal
          src={user.avatarDataUrl}
          onClose={() => setAvatarPreviewOpen(false)}
        />
      ) : null}

      {deleteOpen ? (
        <ConfirmDeleteModal
          confirmText={deleteConfirmText}
          password={deletePassword}
          busy={deleteBusy}
          onChangeConfirmText={setDeleteConfirmText}
          onChangePassword={setDeletePassword}
          onClose={() => {
            if (!deleteBusy) {
              setDeleteOpen(false);
              setDeleteConfirmText("");
              setDeletePassword("");
            }
          }}
          onConfirm={handleDeleteAccount}
        />
      ) : null}
    </div>
  );
}

function SectionCard({
  children,
  title,
  subtitle,
}: {
  children: React.ReactNode;
  title?: string;
  subtitle?: string;
}) {
  return (
    <section className="app-card rounded-3xl p-5">
      {title ? (
        <div className="mb-4">
          <h2 className="text-lg font-semibold">{title}</h2>
          {subtitle ? (
            <p className="mt-1 text-sm app-text-muted">{subtitle}</p>
          ) : null}
        </div>
      ) : null}
      {children}
    </section>
  );
}

function FieldRow({
  label,
  description,
  htmlFor,
  children,
}: {
  label: string;
  description?: string;
  htmlFor?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-2">
      <div>
        {htmlFor ? (
          <label htmlFor={htmlFor} className="text-sm font-semibold">
            {label}
          </label>
        ) : (
          <div className="text-sm font-semibold">{label}</div>
        )}
        {description ? (
          <div className="text-sm app-text-muted">{description}</div>
        ) : null}
      </div>
      {children}
    </div>
  );
}

function ChoiceButton({
  active,
  onClick,
  children,
}: {
  active?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={classNames(
        "rounded-2xl border px-3 py-2 text-sm font-medium transition",
        active
          ? "border-[var(--accent)] bg-[var(--accent)] text-white"
          : "border-[var(--border-main)] bg-[var(--bg-soft)] app-text-soft"
      )}
    >
      {children}
    </button>
  );
}

function ToggleRow({
  label,
  description,
  checked,
  onChange,
}: {
  label: string;
  description?: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}) {
  const switchId = React.useId();

  return (
    <div className="flex items-start justify-between gap-4 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
      <div className="min-w-0 flex-1">
        <label
          htmlFor={switchId}
          className="cursor-pointer text-sm font-semibold"
        >
          {label}
        </label>
        {description ? (
          <div className="mt-1 text-sm app-text-muted">{description}</div>
        ) : null}
      </div>

      <label
        htmlFor={switchId}
        className="relative mt-0.5 inline-flex cursor-pointer items-center"
      >
        <input
          id={switchId}
          type="checkbox"
          checked={checked}
          onChange={(e) => onChange(e.target.checked)}
          className="peer sr-only"
          aria-label={label}
        />
        <span className="block h-7 w-12 rounded-full bg-slate-400/35 transition peer-checked:bg-[var(--accent)]" />
        <span className="absolute left-1 top-1 h-5 w-5 rounded-full bg-white shadow-sm transition peer-checked:left-6" />
      </label>
    </div>
  );
}

function InfoBox({ title, value }: { title: string; value: string }) {
  return (
    <div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] p-4">
      <div className="text-xs uppercase tracking-wide app-text-muted">
        {title}
      </div>
      <div className="mt-2 text-sm font-semibold">{value}</div>
    </div>
  );
}

function ActionButton({
  children,
  onClick,
  primary,
  dangerSoft,
}: {
  children: React.ReactNode;
  onClick: () => void;
  primary?: boolean;
  dangerSoft?: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={classNames(
        "rounded-2xl px-4 py-2.5 text-sm font-semibold transition hover:opacity-90",
        primary
          ? "bg-[var(--accent)] text-white"
          : dangerSoft
          ? "border border-red-500/15 bg-[var(--danger-soft)] text-[var(--danger)]"
          : "border border-[var(--border-main)] bg-[var(--bg-soft)] text-[var(--text-main)]"
      )}
    >
      {children}
    </button>
  );
}

function InfoLine({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-start justify-between gap-3 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
      <div className="text-sm app-text-muted">{label}</div>
      <div className="text-right text-sm font-semibold">{value}</div>
    </div>
  );
}

function QuickInfoCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="app-card-strong rounded-2xl p-3">
      <div className="text-xs uppercase tracking-wide app-text-muted">
        {label}
      </div>
      <div className="mt-1 text-base font-semibold">{value}</div>
    </div>
  );
}

function ChecklistItem({
  children,
  done,
}: {
  children: React.ReactNode;
  done?: boolean;
}) {
  return (
    <div className="flex items-start gap-3 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3">
      <div
        className={classNames(
          "mt-0.5 flex h-5 w-5 items-center justify-center rounded-full text-[11px] font-bold",
          done
            ? "bg-[var(--success-soft)] text-[var(--success)]"
            : "bg-[var(--warning-soft)] text-[var(--warning)]"
        )}
      >
        {done ? "✓" : "!"}
      </div>
      <div className="text-sm">{children}</div>
    </div>
  );
}

function ImagePreviewModal({
  src,
  onClose,
}: {
  src: string;
  onClose: () => void;
}) {
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 px-4"
      onClick={onClose}
    >
      <div
        className="relative max-h-[90vh] max-w-[90vw]"
        onClick={(e) => e.stopPropagation()}
      >
        <button
          type="button"
          onClick={onClose}
          className="absolute right-3 top-3 z-10 rounded-full bg-black/60 px-3 py-2 text-sm font-semibold text-white"
        >
          Đóng
        </button>
        <img
          src={src}
          alt="Xem ảnh đại diện"
          className="max-h-[90vh] max-w-[90vw] rounded-3xl object-contain shadow-2xl"
        />
      </div>
    </div>
  );
}

function ConfirmDeleteModal({
  confirmText,
  password,
  busy,
  onChangeConfirmText,
  onChangePassword,
  onClose,
  onConfirm,
}: {
  confirmText: string;
  password: string;
  busy: boolean;
  onChangeConfirmText: (value: string) => void;
  onChangePassword: (value: string) => void;
  onClose: () => void;
  onConfirm: () => void;
}) {
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/55 px-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="delete-account-title"
      aria-describedby="delete-account-description"
    >
      <div className="w-full max-w-lg rounded-[28px] border border-[var(--border-main)] bg-[var(--bg-card-strong)] p-5 shadow-2xl">
        <div className="flex items-start gap-3">
          <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[var(--danger-soft)] text-xl text-[var(--danger)]">
            !
          </div>
          <div className="flex-1">
            <h3 id="delete-account-title" className="text-xl font-semibold">
              Xoá tài khoản?
            </h3>
            <p
              id="delete-account-description"
              className="mt-1 text-sm app-text-muted"
            >
              Hành động này sẽ xoá toàn bộ dữ liệu gắn với tài khoản hiện tại và
              không thể hoàn tác.
            </p>
          </div>
        </div>

        <div className="mt-5 rounded-2xl border border-red-500/15 bg-[var(--danger-soft)] px-4 py-3 text-sm text-[var(--danger)]">
          Nhập <strong>DELETE</strong> và mật khẩu hiện tại để xác nhận.
        </div>

        <div className="mt-4 space-y-3">
          <div>
            <label htmlFor="delete-account-confirm" className="mb-1 block text-sm font-medium">
              Mã xác nhận
            </label>
            <input
              id="delete-account-confirm"
              value={confirmText}
              onChange={(e) => onChangeConfirmText(e.target.value)}
              placeholder="Gõ DELETE"
              className="app-input w-full rounded-2xl px-3 py-3 text-sm outline-none"
            />
          </div>

          <div>
            <label htmlFor="delete-account-password" className="mb-1 block text-sm font-medium">
              Mật khẩu hiện tại
            </label>
            <input
              id="delete-account-password"
              type="password"
              value={password}
              onChange={(e) => onChangePassword(e.target.value)}
              placeholder="Nhập mật khẩu hiện tại"
              className="app-input w-full rounded-2xl px-3 py-3 text-sm outline-none"
            />
          </div>
        </div>

        <div className="mt-5 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
          <button
            type="button"
            onClick={onClose}
            disabled={busy}
            className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-4 py-3 text-sm font-semibold"
          >
            Huỷ
          </button>

          <button
            type="button"
            onClick={onConfirm}
            disabled={
              busy ||
              confirmText.trim().toUpperCase() !== "DELETE" ||
              !password.trim()
            }
            className="rounded-2xl bg-red-600 px-4 py-3 text-sm font-semibold text-white disabled:opacity-60"
          >
            {busy ? "Đang xử lý..." : "Xoá tài khoản"}
          </button>
        </div>
      </div>
    </div>
  );
}